//! The regions that can be downloaded: the US states (except Alaska), the
//! District of Columbia, Puerto Rico and the US Virgin Islands, from Geofabrik.
//! The table is generated by `tools/make-regions.py`.
use crate::package::Region;

#[path = "regions_data.rs"]
mod data;

pub use data::ALL;

/// The region with this ID (`us-il`), if it is in the catalog.
pub fn find(id: &str) -> Option<&'static Region> {
    ALL.iter().find(|r| r.id == id)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn catalog_is_consistent() {
        assert_eq!(ALL.len(), 52);
        assert_eq!(find("us-il"), Some(&crate::package::ILLINOIS));
        assert!(find("us-ak").is_none());
        let mut ids: Vec<_> = ALL.iter().map(|r| r.id).collect();
        ids.sort_unstable();
        ids.dedup();
        assert_eq!(ids.len(), ALL.len());
        for r in &ALL {
            assert!(r.id.starts_with("us-") && r.id.len() == 5, "{}", r.id);
            assert!(r.package_url.ends_with("-shortbread-1.0.mbtiles"));
            assert!(r.extras_url.ends_with("-latest.osm.pbf"));
            assert!(r.package_bytes > 0 && r.extras_bytes > 0);
            let o = r.outer;
            assert!(o.west < o.east && o.south < o.north, "{}", r.name);
            for (lon, lat) in r.required_points {
                assert!((o.west..=o.east).contains(lon) && (o.south..=o.north).contains(lat));
            }
        }
        assert_eq!(find("us-dc").unwrap().name, "District of Columbia");
        assert_eq!(find("us-vi").unwrap().name, "US Virgin Islands");
    }
}
